use super::*;
#[test]
fn native_catalog_empty_alternate_and_refused_owners_match_portable_corpus(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let empty=read_native_catalog_v1(&fixture["empty"].to_string()).unwrap();assert!(empty.plugins.is_empty());let alternate=read_native_catalog_v1(&fixture["alternate"].to_string()).unwrap();assert_eq!(alternate.registry_id("draft"),fixture["expected"]["registryId"].as_str().unwrap());assert_eq!(alternate.app_id("draft"),fixture["expected"]["app"].as_str());let extensions=alternate.extensions_of("drawing").map(|row|row.plugin_id.as_str()).collect::<Vec<_>>();let expected=fixture["expected"]["extensions"].as_array().unwrap().iter().map(|value|value.as_str().unwrap()).collect::<Vec<_>>();assert_eq!(extensions,expected);for invalid in fixture["refused"].as_array().unwrap(){assert!(read_native_catalog_v1(&invalid.to_string()).is_err());}assert!(load_native_catalog_v1(None).unwrap().plugins.is_empty());assert!(load_native_catalog_v1(Some(Path::new("relative"))).is_err());}

#[test]
fn supplied_catalog_path_refuses_missing_and_malformed_and_reads_actual_publication(){let output=std::env::var("SEMIO_TEST_ARTIFACT_DIR").unwrap();let directory=std::path::PathBuf::from(output).join(format!("io-{}",std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));std::fs::create_dir_all(&directory).unwrap();assert!(load_native_catalog_v1(Some(&directory)).is_err());std::fs::write(directory.join("🦀️catalog.json"),"broken").unwrap();assert!(load_native_catalog_v1(Some(&directory)).is_err());let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();std::fs::write(directory.join("🦀️catalog.json"),fixture["alternate"].to_string()).unwrap();let loaded=load_native_catalog_v1(Some(&directory)).unwrap();assert_eq!(loaded.registry_id("sketch"),"drawing");std::fs::remove_dir_all(directory).unwrap();}
